"use client";

import { useState } from "react";
import {
  motion,
  useMotionTemplate,
  useReducedMotion,
  useSpring,
} from "motion/react";
import "./focus-cursor.css";

export interface FocusCursorProps {
  src: string;
  alt: string;
  label?: string;
}

/** A local color-reveal lens. The native cursor remains available. */
export function FocusCursor({
  src,
  alt,
  label = "A closer look",
}: FocusCursorProps) {
  const [pinned, setPinned] = useState(false);
  const [hover, setHover] = useState(false);
  const reduce = useReducedMotion();
  const x = useSpring(150, { stiffness: 220, damping: 28 });
  const y = useSpring(130, { stiffness: 220, damping: 28 });
  const clipPath = useMotionTemplate`circle(80px at ${x}px ${y}px)`;
  function center(node: HTMLElement) {
    x.jump(node.clientWidth / 2);
    y.jump(node.clientHeight / 2);
  }
  return (
    <button
      className="forme-focus"
      aria-label={`${label}: ${pinned ? "unpin" : "pin"} the color lens`}
      aria-pressed={pinned}
      onPointerMove={(event) => {
        if (event.pointerType !== "mouse" || reduce) return;
        const box = event.currentTarget.getBoundingClientRect();
        x.set(event.clientX - box.left);
        y.set(event.clientY - box.top);
        setHover(true);
      }}
      onPointerLeave={() => setHover(false)}
      onClick={(event) => {
        center(event.currentTarget);
        setPinned(!pinned);
      }}
    >
      <img src={src} alt={alt} loading="lazy" />
      <motion.img
        src={src}
        alt=""
        aria-hidden="true"
        loading="lazy"
        style={{ clipPath, opacity: hover || pinned ? 1 : 0 }}
      />
      <span className="forme-focus-label">
        {label}
        <span aria-hidden="true">{pinned ? "−" : "+"}</span>
      </span>
      <span className="forme-focus-hint">
        {pinned
          ? "Lens pinned · select to release"
          : "Move to explore · tap to pin"}
      </span>
    </button>
  );
}

.forme-focus {
  position: relative;
  display: block;
  width: 100%;
  height: 100%;
  min-height: 270px;
  overflow: hidden;
  border: 0;
  padding: 0;
  background: #45554d;
  cursor: crosshair;
  color: white;
  text-align: left;
  font: inherit;
}
.forme-focus > img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.forme-focus > img:first-child {
  filter: grayscale(1) brightness(0.7);
}
.forme-focus > img:nth-child(2) {
  transition: opacity 0.25s;
}
.forme-focus-label {
  position: absolute;
  left: 24px;
  right: 24px;
  top: 23px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 16px;
  letter-spacing: -0.04em;
  text-shadow: 0 1px 8px #000b;
}
.forme-focus-label > span {
  font-size: 25px;
}
.forme-focus-hint {
  position: absolute;
  bottom: 22px;
  left: 24px;
  padding: 7px 10px;
  border: 1px solid #ffffff50;
  border-radius: 20px;
  background: #15251ca8;
  backdrop-filter: blur(5px);
  font-size: 10px;
  color: #fff;
}
.forme-focus:focus-visible {
  outline: 3px solid #617cf5;
  outline-offset: -5px;
}
@media (prefers-reduced-motion: reduce) {
  .forme-focus > img:nth-child(2) {
    transition: none;
  }
}
